async function json<T>(res: Response): Promise<T> {
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return (await res.json()) as T;
}

export async function loadDashboard(render: (me: User, users: User[]) => void): Promise<void> {
  const me = await fetchCurrentUser();
  const users = await fetchUserList();
  render(me, users);
}

export function mountDashboard(root: HTMLElement): void {
  root.textContent = "Loading...";
  void loadDashboard((me: User, users: User[]) => {
    root.textContent = `${me.name}: ${users.length} users`;
  });
}

export async function fetchUserList(): Promise<User[]> {
  try {
    const res = await fetch("/api/admin/users");
    if (!res.ok) return [];
    return ((await res.json()) as { users: User[] }).users ?? [];
  } catch {
    return [];
  }
}
